$ErrorActionPreference='Stop';$root=$PSScriptRoot;$s75="$root/training/textdata32-v1";$data=[IO.Path]::GetFullPath($env:TARTARUS75_OUT)
[void][IO.Directory]::CreateDirectory($data);$ascii=[Text.Encoding]::ASCII
. "$root/headadapt32-launcher.ps1"
. "$root/tools/io-audit-v2/RawJournal.ps1"
$script:cache75=[Collections.Generic.Dictionary[string,byte[]]]::new([StringComparer]::Ordinal)
$script:physical75=0;$script:failed75=0;$script:uncached75=0;$script:journal75=$null;$script:phase75='';$script:journals75=[Collections.Generic.List[string]]::new()
$script:assertions75=[Collections.Generic.List[byte]]::new();$script:names75=[Collections.Generic.List[string]]::new();$script:refusals75=0
function Bytes75([string]$text){return ,$ascii.GetBytes($text)}
function Join75([byte[][]]$parts){$m=[IO.MemoryStream]::new();try{foreach($part in $parts){$m.Write($part,0,$part.Length)};return ,$m.ToArray()}finally{$m.Dispose()}}
function Slice75([byte[]]$bytes,$offset,$count){$result=[byte[]]::new($count);[Array]::Copy($bytes,$offset,$result,0,$count);return ,$result}
function Save75($name,[byte[]]$bytes){[IO.File]::WriteAllBytes("$data/$name",$bytes)}
function Json75($name,$value){[IO.File]::WriteAllText("$data/$name",(ConvertTo-Json -InputObject $value -Depth 12),[Text.UTF8Encoding]::new($false))}
function Logical75([byte[]]$raw){$m=[IO.MemoryStream]::new();try{for($i=0;$i -lt $raw.Length;$i++){if($raw[$i] -eq 13 -and $i+1 -lt $raw.Length -and $raw[$i+1] -eq 10){continue};$m.WriteByte($raw[$i])};return ,$m.ToArray()}finally{$m.Dispose()}}
function Run75($relative,[byte[]]$payload,[switch]$Uncached){
 if($null -eq $script:journal75){throw 'BF call outside journal75'};if($null -eq $payload){$payload=[byte[]]@()};$path=Join-Path $root $relative;$key=$path+':'+[Convert]::ToBase64String($payload)
 if(-not $Uncached -and $script:cache75.ContainsKey($key)){return ,$script:cache75[$key]}
 try{$raw=LaunchRaw74 $path $payload}catch{$script:failed75++;$e=$_.Exception;while($null -ne $e -and -not $e.Data.Contains('TartarusRaw74')){$e=$e.InnerException};Save75 "failed-$script:failed75.input" $payload;if($null -ne $e -and $e.Data['TartarusStarted74']){$partial=[byte[]]$e.Data['TartarusRaw74'];[void]$script:journal75.Append($path,$script:phase75,'failed-process',$payload,$partial);$script:physical75++;Save75 "failed-$script:failed75.raw" $partial};Json75 "failed-$script:failed75.json" @{Error=$_.Exception.Message;NumericalPass=$false};throw}
 $kind=if($Uncached){$script:uncached75++;'uncached-control'}else{'fresh'};[void]$script:journal75.Append($path,$script:phase75,$kind,$payload,$raw);$script:physical75++
 $logical=Logical75 $raw;if(-not $Uncached){$script:cache75[$key]=$logical};return ,$logical
}
function Check75($name,[byte[]]$expected,[byte[]]$actual,[switch]$Mismatch){
 if($expected.Length -ne $actual.Length){if($Mismatch){$script:assertions75.Add(48);$script:names75.Add($name+' physical refusal');$script:refusals75++;return};throw ('Physical framing75 '+$name+' '+$expected.Length+'/'+$actual.Length)}
 $different=$false
 for($offset=0;$offset -lt $expected.Length;$offset+=200){$count=[Math]::Min(200,$expected.Length-$offset);$payload=Join75 @((Bytes75 $count.ToString('000')),(Slice75 $expected $offset $count),(Slice75 $actual $offset $count));$v=Run75 'training/codec32-v11/verify.bf' $payload;$script:lastCertificate75=$v;if($ascii.GetString($v) -ceq "FAIL`n"){$different=$true}elseif($ascii.GetString($v) -cne "PASS`n"){throw ('Invalid BF certificate75 '+$name)}}
 if($different -ne [bool]$Mismatch){Save75 failure.expected $expected;Save75 failure.actual $actual;Json75 failure.json @{Assertion=$name;ExpectedMismatch=[bool]$Mismatch};throw ('BF comparison75 '+$name)};$script:assertions75.Add(48);$script:names75.Add($name);if($Mismatch){$script:refusals75++}
}
function Start75($name){if($null -ne $script:journal75){throw 'Journal already open75'};$script:phase75=$name;$relative='bf-raw75/'+$name;$script:journal75=New-TartarusRawJournal -Directory "$data/$relative";$script:journals75.Add($relative);$script:clock75=[Diagnostics.Stopwatch]::StartNew();Write-Host ('stage75 START '+$name)}
function Close75([switch]$Failed){try{$capture=$script:journal75.Complete()}finally{$script:journal75.Dispose();$script:journal75=$null};$script:clock75.Stop();Json75 ($script:phase75+'.capture.json') @{Capture=$capture;NumericalStatus=$(if($Failed){'FAIL'}else{'PASS'});ElapsedMilliseconds=$script:clock75.ElapsedMilliseconds};Write-Host ('stage75 DONE '+$script:phase75+' origins='+$script:physical75+' elapsed='+$script:clock75.Elapsed.ToString())}
function Phase75($name,[scriptblock]$action){Start75 $name;$ok=$false;try{& $action;$ok=$true}finally{Close75 -Failed:(!$ok)}}
function Finish75(){$expected=[byte[]](@(48)*$script:assertions75.Count);Check75 'all assertion flags75' $expected $script:assertions75.ToArray();Save75 aggregate.out $script:lastCertificate75;Save75 assertions.flags $script:assertions75.ToArray();[IO.File]::WriteAllLines("$data/assertions.manifest",$script:names75,$ascii);Json75 ledger.json @{Stage=75;Assertions=$script:assertions75.Count;ExpectedRefusals=$script:refusals75;PhysicalOrigins=$script:physical75;FailedPhysical=$script:failed75;UncachedControls=$script:uncached75;Journals=$script:journals75.ToArray();Aggregate='PASS';ValidationNumericalRuns=0;TestNumericalRuns=0;NeuralTrainingRuns=0;ModelArithmetic='BF'};if($script:failed75 -ne 0){throw 'Physical failure75 cannot pass'}}
function Counted75([byte[]]$raw){$meta=Run75 'training/codec32-v11/metadata-to-count.bf' (Bytes75 ($raw.Length.ToString()+[char]10));if($meta.Length -ne 3){throw 'Count metadata framing75'};Check75 'BF metadata valid75' (Bytes75 '0') (Slice75 $meta 0 1);return ,(Join75 @((Slice75 $meta 1 2),$raw))}
function Label75([byte[]]$id){return ,(Run75 'training/objective32-v11/target-label-clean.bf' $id)}
function Add75([byte[]]$a,[byte[]]$b){$pairs=[byte[]]::new(10);for($j=0;$j -lt 5;$j++){$pairs[2*$j]=$a[4-$j];$pairs[2*$j+1]=$b[4-$j]};return ,(Run75 'training/headobjective32-v11/add5.bf' $pairs)}
function SumTriples75([byte[][]]$triples,$name){if($triples.Count -gt 28){throw 'SumTriples75 max28'};$payload=[byte[]]@();$sum=Bytes75 '00000';for($j=0;$j -lt 28;$j++){$one=if($j -lt $triples.Count){$triples[$j]}else{Bytes75 '000'};$payload=Join75 @($payload,$one);$sum=Add75 $sum (Join75 @((Bytes75 '00'),$one))};$reference=Run75 'training/headcontext32-v11/reference-sum5.bf' $payload;Check75 ('independent sum75 '+$name) $reference $sum;return ,$sum}
function SumFlags75([byte[]]$values,$name){$blocks=[Collections.Generic.List[byte[]]]::new();for($j=0;$j -lt $values.Length;$j++){$blocks.Add((Join75 @((Bytes75 '00'),(Slice75 $values $j 1))))};do{$next=[Collections.Generic.List[byte[]]]::new();for($start=0;$start -lt $blocks.Count;$start+=28){$group=[Collections.Generic.List[byte[]]]::new();for($j=$start;$j -lt [Math]::Min($start+28,$blocks.Count);$j++){$group.Add($blocks[$j])};$sum=SumTriples75 $group.ToArray() ($name+'/'+$start);if($blocks.Count -gt 28){Check75 'bounded intermediate75' (Bytes75 '00') (Slice75 $sum 0 2)};$next.Add((Slice75 $sum 2 3))};$blocks=$next}while($blocks.Count -gt 1);return ,$sum}
function Max75([byte[]]$a,[byte[]]$b){$pairs=[byte[]]::new(8);for($j=0;$j -lt 4;$j++){$pairs[2*$j]=$a[$j];$pairs[2*$j+1]=$b[$j]};return ,(Run75 'training/headobjective32-v11/max-word.bf' (Join75 @($pairs,$a,$b)))}
function EqualWord75([byte[]]$a,[byte[]]$b){$parts=Join75 @((Run75 'training/headobjective32-v11/error.bf' (Join75 @((Slice75 $a 0 2),(Slice75 $b 0 2)))),(Run75 'training/headobjective32-v11/error.bf' (Join75 @((Slice75 $a 2 2),(Slice75 $b 2 2)))),(Bytes75 '0000'));$m=Run75 'training/separability32-v11/any6.bf' $parts;return ,(Run75 'training/learnability32-v11/certificate.bf' (Join75 @($m,(Bytes75 '1'))))}
